<script>
const cctvMapNodes = @json($topologyNodes);
const cctvMapLinks = @json($topologyLinks);
function renderCctvMap(){const map=document.getElementById('cctvMap'),layer=document.getElementById('cctvMapNodes'),svg=document.getElementById('cctvMapSvg'),empty=document.getElementById('cctvMapEmpty');if(!map)return;layer.innerHTML='';svg.innerHTML='';empty.style.display=cctvMapLinks.length?'none':'block';const recorders=cctvMapNodes.filter(node=>['nvr','dvr'].includes(node.type));const cameras=cctvMapNodes.filter(node=>!['nvr','dvr'].includes(node.type));const positions={};recorders.forEach((node,index)=>{positions[node.id]={x:(index+1)*map.clientWidth/(recorders.length+1),y:76};});cameras.forEach((node,index)=>{positions[node.id]={x:(index+1)*map.clientWidth/(cameras.length+1),y:330};});cctvMapLinks.forEach(link=>{const source=positions[link.source],target=positions[link.target];if(!source||!target)return;const line=document.createElementNS('http://www.w3.org/2000/svg','path');const mid=(source.y+target.y)/2;line.setAttribute('d','M '+source.x+' '+source.y+' L '+source.x+' '+mid+' L '+target.x+' '+mid+' L '+target.x+' '+target.y);line.setAttribute('fill','none');line.setAttribute('stroke',link.status==='connected'?'#0f766e':link.status==='degraded'?'#f59e0b':'#dc2626');line.setAttribute('stroke-width','3');line.setAttribute('stroke-dasharray',link.status==='connected'?'0':'7 5');svg.appendChild(line);});cctvMapNodes.forEach(node=>{const position=positions[node.id];if(!position)return;const element=document.createElement('a');element.href='{{ route('cctv.index') }}?edit='+node.id;element.className='cctv-map-node '+(['nvr','dvr'].includes(node.type)?'recorder ':'')+node.status;element.style.left=position.x+'px';element.style.top=position.y+'px';element.innerHTML='<div class="map-node-title"><span class="map-node-icon">'+(['nvr','dvr'].includes(node.type)?'NVR':'TV')+'</span><span>'+escapeCctvMap(node.name)+'</span></div><small>'+escapeCctvMap(node.code)+' · '+escapeCctvMap(node.status)+'</small>';layer.appendChild(element);});}
function escapeCctvMap(value){const div=document.createElement('div');div.textContent=value||'';return div.innerHTML}function fitCctvMap(){renderCctvMap()}window.addEventListener('resize',renderCctvMap);renderCctvMap();
</script>
